import React from "react";
import { graphql, Link } from "gatsby";
import { GatsbyImage, getImage } from "gatsby-plugin-image";
import { ArrowRight, Code2 } from "lucide-react";
import Layout from "../components/layout/layout";
import { SEO as Seo } from "../components/seo";
import { collectProjectStories } from "../lib/projectStories.cjs";
import { seriesPath } from "../lib/series.cjs";
import { withSizes } from "../lib/images";
import "../styles/projects.css";

export default function Projects({ data }) {
  const stories = collectProjectStories(data.allMdx.nodes);
  return (
    <Layout>
      <section className="page-intro">
        <h1>Projects</h1>
        <p>From the first idea to the working system. Explore the builds and the decisions behind them, one part at a time.</p>
      </section>
      <section className="project-index" aria-label="All projects">
        <div className="project-index-meta">
          <span>{stories.length} {stories.length === 1 ? "project" : "projects"}</span>
          <span>Latest published part first</span>
        </div>
        {stories.map((story) => {
          const image = withSizes(getImage(story.posts[0].frontmatter.featuredImage), "(min-width: 761px) 360px, calc(100vw - 64px)");
          return (
            <article className="project-index-entry" key={story.id}>
              <Link className="project-index-link" to={seriesPath(story.id)}>
                <div className="project-index-cover">
                  {image ? <GatsbyImage image={image} alt="" /> : <div className="image-placeholder"><Code2 size={44} aria-hidden="true" /></div>}
                </div>
                <div className="project-index-copy">
                  <span className="project-index-parts">{story.posts.length} parts</span>
                  <h2>{story.title}</h2>
                  <p>{story.description}</p>
                  <span className="project-index-action">Explore project <ArrowRight size={18} aria-hidden="true" /></span>
                </div>
              </Link>
            </article>
          );
        })}
        {!stories.length && <p className="project-index-empty">Project stories are on the way. <Link to="/blog/">Browse the articles</Link> in the meantime.</p>}
      </section>
    </Layout>
  );
}

export const query = graphql`
  query ProjectIndex {
    allMdx(filter: { frontmatter: { draft: { ne: true }, series: { ne: null } } }) {
      nodes { ...PostCardData }
    }
  }
`;

export const Head = () => <Seo title="Projects" pathname="/projects/" description="Explore embedded systems and software projects, from the initial idea to a working system, with the full story in reading order." />;
