const { collectSeries } = require("./series.cjs");

// Project introductions belong to the collection, not to an individual part.
const introductions = {
  scenesense: {
    title: "SceneSense",
    description: "A GoPro camera workstation, from the Qt Quick interface and local object detection to a Raspberry Pi system built with Yocto.",
  },
};

function collectProjectStories(posts) {
  // A showcase only promises parts a visitor can read on the public site.
  const published = posts.filter(({ frontmatter }) => frontmatter.draft !== true);
  return collectSeries(published)
    .filter(({ posts: parts }) => parts.length > 1)
    .map((group) => {
      const latestPublishedAt = Math.max(...group.posts.map(({ frontmatter }) =>
        Date.parse(frontmatter.publishedAt || frontmatter.date) || 0));
      return {
        ...group,
        title: introductions[group.id]?.title || group.title,
        description: introductions[group.id]?.description || group.posts[0].frontmatter.description || "Explore the project, one part at a time.",
        firstSlug: group.posts[0].frontmatter.slug,
        latestPublishedAt,
      };
    })
    .sort((a, b) => b.latestPublishedAt - a.latestPublishedAt || a.id.localeCompare(b.id));
}

module.exports = { collectProjectStories };
